import{_ as a,o,c as s,a2 as t}from"./chunks/framework.BKIQXCqS.js";const m=JSON.parse('{"title":"Documentación","description":"","frontmatter":{},"headers":[],"relativePath":"es/doc.md","filePath":"es/doc.md"}'),r={name:"es/doc.md"};function n(i,e,c,d,l,u){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="documentacion" tabindex="-1">Documentación <a class="header-anchor" href="#documentacion" aria-label="Permalink to &quot;Documentación&quot;">​</a></h1><p>La extensión funciona en <strong>Chrome 120</strong> y versiones posteriores, y en <strong>Firefox 136</strong> y versiones posteriores.</p><h2 id="user-scripts" tabindex="-1">Permitir los scripts de usuario <a class="header-anchor" href="#user-scripts" aria-label="Permalink to &quot;Permitir los scripts de usuario {#user-scripts}&quot;">​</a></h2><p>Los navegadores solo ejecutan el JavaScript de una extensión en las páginas web con un permiso aparte. Sin él, los estilos de las reglas se siguen aplicando, pero su JavaScript no se ejecuta; en ese caso, la ventana emergente y la página de opciones explican cómo activarlo.</p><ul><li><strong>Chrome 138 y versiones posteriores:</strong> abre los detalles de la extensión (<code>chrome://extensions</code> → User JavaScript and CSS → «Detalles») y activa «Permitir secuencias de comandos de usuario». No hace falta el modo de desarrollador.</li><li><strong>Chrome 120–137:</strong> activa «Modo de desarrollador» en la esquina superior derecha de <code>chrome://extensions</code>. Es un <a href="https://developer.chrome.com/docs/extensions/reference/api/userScripts#developer_mode_for_extension_users" target="_blank" rel="noreferrer">requisito de Google</a> para todas las extensiones con scripts de usuario.</li><li><strong>Firefox:</strong> haz clic en «Permitir scripts de usuario» en la ventana emergente y confírmalo en el diálogo del navegador. Firefox también puede dejar la extensión sin acceso a los sitios: entonces la ventana emergente muestra «Permitir acceso a sitios», y la página de opciones, «Permitir» en un aviso en la parte superior.</li></ul><h2 id="reglas" tabindex="-1">Reglas <a class="header-anchor" href="#reglas" aria-label="Permalink to &quot;Reglas&quot;">​</a></h2><p>En el contexto de la extensión, una <code>regla</code> es código JavaScript o CSS (o ambos) que se ejecuta en las páginas web que coinciden con sus patrones de URL.</p><h3 id="url-patterns" tabindex="-1">Patrones de URL <a class="header-anchor" href="#url-patterns" aria-label="Permalink to &quot;Patrones de URL {#url-patterns}&quot;">​</a></h3><ul><li>Un patrón tiene la forma <code>&lt;scheme&gt;://&lt;host&gt;/&lt;path&gt;</code>: <code>https://site.com/*</code>;</li><li>Varios patrones se separan con comas: <code>https://one.com/*, https://two.com/*</code>;</li><li>Una exclusión se marca con <code>!</code>: <code>!https://site.com/admin/*</code>.</li></ul><p>La extensión convierte cada patrón al formato de <a href="https://developer.chrome.com/docs/extensions/develop/concepts/match-patterns" target="_blank" rel="noreferrer">patrón de coincidencia</a> del navegador, y la ventana emergente y el contador en el icono muestran exactamente dónde ejecutará la regla el navegador.</p><p><strong>Un patrón con esquema</strong> se usa casi tal como está escrito:</p><table tabindex="0"><thead><tr><th>Escribes</th><th>La regla se ejecuta en</th></tr></thead><tbody><tr><td><code>https://site.com/*</code></td><td><code>site.com</code> y <code>www.site.com</code>, no en otros subdominios</td></tr><tr><td><code>https://*.site.com/*</code></td><td><code>site.com</code> y todos sus subdominios</td></tr><tr><td><code>https://site.com/path</code></td><td>las páginas que empiezan por <code>/path</code> en <code>site.com</code> y <code>www.site.com</code></td></tr><tr><td><code>https://site.com</code></td><td>todo <code>site.com</code> y <code>www.site.com</code></td></tr><tr><td><code>http*://site.com</code></td><td><code>site.com</code> y <code>www.site.com</code> por http y https</td></tr><tr><td><code>http://localhost:*/*</code></td><td>localhost en cualquier puerto</td></tr></tbody></table><p><strong>Un patrón sin esquema</strong> significa el sitio con sus subdominios, por http y https:</p><table tabindex="0"><thead><tr><th>Escribes</th><th>La regla se ejecuta en</th></tr></thead><tbody><tr><td><code>site.com</code>, <code>*site.com*</code>, <code>*.site.com</code></td><td><code>site.com</code> y todos sus subdominios</td></tr><tr><td><code>www.site.com</code></td><td><code>www.site.com</code> y <code>site.com</code></td></tr><tr><td><code>пример.рф</code></td><td><code>пример.рф</code> y sus subdominios</td></tr><tr><td><code>site.com/path</code></td><td>las páginas que empiezan por <code>/path</code> en <code>site.com</code> y sus subdominios</td></tr><tr><td><code>localhost:3000</code></td><td>localhost en el puerto 3000</td></tr><tr><td><code>/admin</code></td><td>las páginas con <code>/admin</code> en la ruta, en cualquier sitio</td></tr><tr><td><code>*</code></td><td>cualquier sitio</td></tr></tbody></table><p>Una exclusión con esquema se usa exactamente como está escrita: <code>https://site.com/*, !https://www.site.com/*</code> se ejecuta en <code>site.com</code>, pero no en <code>www.site.com</code>. Una exclusión sin esquema sigue la tabla anterior: <code>!site.com/admin</code> excluye <code>/admin</code> en <code>site.com</code> y sus subdominios.</p><p><strong>Puertos en Firefox.</strong> Un patrón de Firefox no puede indicar un puerto, así que el puerto se descarta: <code>localhost:3000</code> se ejecuta en localhost en cualquier puerto, y una exclusión con puerto excluye todos los puertos del host. Un patrón para cualquier sitio en un solo puerto (<code>*://*:8080/*</code>) se convertiría en un patrón para todos los sitios, por eso en Firefox se marca en rojo.</p><p><strong>Se marca en rojo</strong> un patrón que el navegador no acepta: un <code>*</code> dentro del host (<code>https://shop*.site.com/*</code>, <code>https://site.*/*</code>) o un esquema en el que la extensión no puede ejecutarse (<code>chrome-extension://</code>, <code>ws://</code>). Ese patrón se omite y los demás patrones de la regla siguen funcionando. Si se rechaza una exclusión, la regla no se ejecuta en ningún sitio hasta que la corrijas: de lo contrario, se ejecutaría en las páginas que excluiste.</p><h3 id="propiedades-de-javascript" tabindex="-1">Propiedades de JavaScript <a class="header-anchor" href="#propiedades-de-javascript" aria-label="Permalink to &quot;Propiedades de JavaScript&quot;">​</a></h3><p>Los botones del encabezado del panel de JavaScript:</p><ul><li><code>Entorno aislado</code>: el script ve el DOM de la página, pero no sus variables ni sus funciones.</li><li><code>Todos los marcos</code>: el script también se ejecuta en los marcos cuya dirección coincide con la regla. Cada marco se comprueba por separado con los patrones de la regla.</li><li><code>Ejecutar al inicio</code>: el script se ejecuta antes de que se construya el DOM; si no, después, pero antes de que se carguen recursos como imágenes y marcos. Ten en cuenta que el evento <code>DOMContentLoaded</code> no se dispara para un script así.</li></ul><h3 id="propiedades-de-los-estilos" tabindex="-1">Propiedades de los estilos <a class="header-anchor" href="#propiedades-de-los-estilos" aria-label="Permalink to &quot;Propiedades de los estilos&quot;">​</a></h3><p>Los botones del encabezado del panel de estilos:</p><ul><li><code>Preprocesador Sass</code>: activado (por defecto), el estilo se compila como <code>Sass</code> o <code>SCSS</code> y la sintaxis se elige según haya <code>{;}</code> en el código; desactivado, el estilo se aplica tal como está escrito.</li><li><code>!important automático en todas las propiedades</code>: agrega <code>!important</code> a cada propiedad del estilo compilado.</li><li><code>Aplicar en marcos anidados</code>: el estilo también llega a los marcos dentro de la página. Activado por defecto.</li><li><code>Aplicar en shadow DOM</code>: el estilo también se aplica dentro de los componentes web con un shadow DOM abierto. Desactivado por defecto.</li></ul><p>Un estilo cambia en las pestañas abiertas al instante, sin volver a cargar la página: al editarlo, al activar la regla o al cambiar su dirección.</p><h3 id="reglas-compartidas" tabindex="-1">Reglas compartidas <a class="header-anchor" href="#reglas-compartidas" aria-label="Permalink to &quot;Reglas compartidas&quot;">​</a></h3><p>Las reglas compartidas permiten crear dependencias entre reglas y controlar de forma explícita el orden en que se cargan. Cualquier regla se puede marcar como «Regla compartida» en el menú de la regla: así se agrega a la lista de módulos de las demás reglas. De las reglas incluidas solo se toma el contenido JS y CSS; el resto de sus propiedades se ignora.</p><h3 id="versiones-anteriores" tabindex="-1">Versiones anteriores <a class="header-anchor" href="#versiones-anteriores" aria-label="Permalink to &quot;Versiones anteriores&quot;">​</a></h3><p>La extensión guarda el código de una regla antes de cada uno de los últimos 10 guardados: «Versiones anteriores» en el menú de la regla. Una versión vuelve al editor y se aplica después de guardarla. Las versiones se guardan solo en este navegador: no se exportan ni se guardan en la nube.</p><h3 id="otras-funciones" tabindex="-1">Otras funciones <a class="header-anchor" href="#otras-funciones" aria-label="Permalink to &quot;Otras funciones&quot;">​</a></h3><ul><li>El marcador <code>Regla activada</code> se ignora cuando la regla es compartida y otra regla la incluye;</li><li>El marcador <code>Guardar en la nube</code> solo significa que la regla se incluye en la copia de seguridad en la nube;</li><li>«Usar como plantilla para reglas nuevas» en el menú de la regla: las reglas nuevas empiezan con el código y las propiedades de esta regla.</li></ul><h2 id="modulos" tabindex="-1">Módulos <a class="header-anchor" href="#modulos" aria-label="Permalink to &quot;Módulos&quot;">​</a></h2><p>A las reglas se pueden agregar módulos JS y CSS externos, que se ejecutan antes que ellas. Se admiten enlaces <code>https://...</code>; la extensión reconoce el tipo de recurso.</p><p>El contenido del módulo se descarga y se guarda en el almacenamiento de la extensión. Se actualiza con «Volver a descargar» en la ventana de edición del módulo o de forma programada, con el ajuste «Actualización de bibliotecas»: manual, diaria o semanal. Si una descarga falla, se conserva la versión anterior del módulo.</p><h2 id="almacenamiento" tabindex="-1">Almacenamiento <a class="header-anchor" href="#almacenamiento" aria-label="Permalink to &quot;Almacenamiento&quot;">​</a></h2><h3 id="almacenamiento-local" tabindex="-1">Almacenamiento local <a class="header-anchor" href="#almacenamiento-local" aria-label="Permalink to &quot;Almacenamiento local&quot;">​</a></h3><ul><li>«Descargar JSON» guarda tus reglas, bibliotecas y configuración en un archivo.</li><li>«Cargar JSON» abre una lista de las reglas y bibliotecas del archivo. «Agregar selección» agrega las marcadas a las tuyas: las reglas que ya tienes se reemplazan, y su código anterior queda en las versiones anteriores. «Reemplazar todo» reemplaza tus reglas y bibliotecas por las del archivo.</li></ul><h3 id="sincronizacion-del-navegador" tabindex="-1">Sincronización del navegador <a class="header-anchor" href="#sincronizacion-del-navegador" aria-label="Permalink to &quot;Sincronización del navegador&quot;">​</a></h3><p>Si la sincronización está activada en el navegador, puedes subir una copia de seguridad a la nube con tu cuenta de Google o de Firefox. Este método no requiere iniciar sesión aparte ni configurar nada: <code>storage.sync</code> es el <a href="https://developer.chrome.com/docs/extensions/reference/api/storage#storage_areas" target="_blank" rel="noreferrer">tipo de sincronización estándar para extensiones</a>. Las copias de seguridad se suben y se descargan a mano.</p><p>El espacio está limitado a 100 KB, así que antes de subirla se quitan de la copia el contenido de los módulos externos y todos los datos generados, y el resultado se comprime. Si aun así no hay espacio suficiente, desactiva «Guardar en la nube» en las reglas que no necesites en la copia de seguridad.</p><h2 id="mcp" tabindex="-1">Agentes (MCP) <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;Agentes (MCP) {#mcp}&quot;">​</a></h2><p>Los agentes de IA (Claude Code, Codex, Gemini CLI, Cursor, VS Code, Claude Desktop y otros) pueden leer y editar tus reglas a través del servidor MCP local <a href="https://www.npmjs.com/package/user-js-css-mcp" target="_blank" rel="noreferrer">user-js-css-mcp</a>. La función es experimental.</p><ol><li>Abre la sección <strong>MCP</strong> de la página de opciones y activa «Permitir conexiones MCP».</li><li>Elige tu cliente. La sección ofrece un comando listo, un enlace de instalación con un clic o un bloque de configuración, con el secreto de conexión ya incluido.</li><li>Reinicia el cliente: inicia el servidor por sí mismo, y la sección muestra que el cliente está conectado.</li></ol><p>El servidor se ejecuta en tu equipo (<code>127.0.0.1</code>) y requiere Node.js 18+ o Bun 1.2+. La extensión y el servidor comprueban el secreto de conexión antes de cada solicitud, así que otro programa del equipo no puede usarlos. «Reemplazar», junto al secreto, desconecta todos los clientes configurados con el anterior.</p><p>Un agente puede listar, leer, buscar, crear y cambiar reglas y bibliotecas, averiguar qué reglas se ejecutan en una página, leer por qué una regla no funciona, hacer una copia de seguridad de las reglas en un archivo y restaurarlas, y devolver una regla a una versión anterior.</p>',44)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};
